"""DIE-QC-36 A0: install the plan tile tree (opt-in core_infra delta, install_stage pre_cts) into a COPY of a GEOM
PASS-COND kit and chain it at PRE_CTS via core_infra.kit_cts_hook (no re-place: the copy keeps 3_place.odb).
    python3 -I prep_cts.py TOOLDIR KITCOPY SLICE"""
import json, sys
from pathlib import Path
sys.path.insert(0, sys.argv[1])
import core_infra as CI
kd, sl = Path(sys.argv[2]), json.loads(Path(sys.argv[3]).read_text())
# approved generator fix claude/die-qc-35-kitgen-1029@866c6a98e96: gen_core_kit_qc.FC_DT_LIFT_TCL, verbatim
FC_DT_LIFT_TCL = (
    "# GENERATED by gen_core_kit_qc.py: pre-CTS dont_touch lift on the POST_SYNTH face flops (ot_fcap_* / ot_fconst_*)\n"
    "set ::ot_fc_dt {}\nforeach i [[ord::get_db_block] getInsts] { if {[regexp {^ot_fc(ap|onst)_} [$i getName]] && [$i isDoNotTouch]} "
    "{ $i setDoNotTouch 0; lappend ::ot_fc_dt [$i getName] } }\nputs \"OT_FCAP: dont_touch lifted for CTS on [llength $::ot_fc_dt] flops\"\n")
(kd / "fc_dt_lift_cts.tcl").write_text(FC_DT_LIFT_TCL)
pre_gpl = (kd / "master_core_infra.tcl").read_text()
assert CI.install(kd, sl)
assert (kd / "master_core_infra.tcl").read_text() == pre_gpl, "pre-GPL hook changed: the copy would not match its place"
(kd / "master_slice.json").write_text(json.dumps(sl, indent=1) + "\n")
cfg = (kd / "config.mk").read_text().splitlines()
assert CI.kit_cts_hook(kd, cfg)
(kd / "config.mk").write_text("\n".join(cfg) + "\n")
print("PREP_OK", kd, (kd / "fc_dt_lift_cts.tcl").read_text().count("source"), "sources in PRE_CTS hook")
